insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g7_ela_v1'
from (values
('110.23.b.2.A',2,'Which resource would a reader use to find a word''s synonyms?','["a thesaurus", "an almanac", "an atlas", "a phone book"]'::jsonb,0,'A thesaurus lists words with similar meanings.','original'),
('110.23.b.2.A',3,'A reader sees the label ''adj.'' in a dictionary entry for ''gleaming''. What does the label tell the reader?','["the word''s origin", "the word''s part of speech", "the number of syllables", "the pronunciation"]'::jsonb,1,'Adj. stands for adjective.','original'),
('110.23.b.2.A',3,'Which dictionary detail helps a reader pronounce an unfamiliar word?','["the word''s part of speech", "the guide words", "the phonetic spelling and stress marks", "the sample sentence only"]'::jsonb,2,'Phonetic respellings show how to say a word.','original'),
('110.23.b.2.A',4,'A student looks up ''novel'' and finds two entries: one adjective and one noun. How can the student pick the right entry?','["pick the second entry every time", "choose the older entry", "use the entry with fewer letters", "match the word''s use in the sentence to the part of speech"]'::jsonb,3,'Part of speech identifies the meaning.','original'),
('110.23.b.2.B',2,'''Unlike the calm lake, the river was turbulent and wild.'' What does ''turbulent'' mean?','["rough and unsettled", "shallow", "frozen", "quiet"]'::jsonb,0,'''Unlike calm'' signals an opposite.','original'),
('110.23.b.2.B',3,'''Because the road was treacherous, drivers moved slowly and clutched their wheels.'' What does ''treacherous'' mean?','["scenic", "dangerous", "wide", "newly built"]'::jsonb,1,'The cause-effect clue is slow, tense driving.','original'),
('110.23.b.2.B',3,'''Her frugal habits, such as reusing envelopes, saved the family money.'' What is the meaning of ''frugal''?','["wasteful", "noisy", "careful about spending", "famous"]'::jsonb,2,'Reusing envelopes shows saving.','original'),
('110.23.b.2.B',4,'''In contrast to his verbose uncle, Ben answered in a few words.'' What does ''verbose'' mean?','["speaking rudely", "speaking softly", "using few words", "using too many words"]'::jsonb,3,'Contrast with ''a few words'' signals the opposite.','original'),
('110.23.b.2.C',2,'The Greek root ''chron'' means ''time.'' Which word means ''arranged in order of time''?','["chronological", "psychological", "biological", "geological"]'::jsonb,0,'Chrono + logical = time order.','original'),
('110.23.b.2.C',3,'The Latin root ''spect'' means ''look.'' What does ''spectator'' mean?','["a person who sings", "a person who watches", "a person who writes", "a person who builds"]'::jsonb,1,'Spect = look.','original'),
('110.23.b.2.C',3,'The Greek root ''phon'' means ''sound.'' Which instrument name uses it?','["periscope", "telescope", "saxophone", "microscope"]'::jsonb,2,'Phon = sound.','original'),
('110.23.b.2.C',4,'The Latin root ''scrib/script'' means ''write.'' What is a ''manuscript''?','["a speech made aloud", "a map", "a musical instrument", "a handwritten or typed document"]'::jsonb,3,'Manu (hand) + script (write).','original'),
('110.23.b.5.B',3,'A reader generates the question ''What evidence supports the author''s claim?'' This is most useful to...','["evaluate the argument", "count the pages", "name the publisher", "find the font"]'::jsonb,0,'Questions guide analysis.','original'),
('110.23.b.5.B',3,'While reading a mystery, which question best helps predict what comes next?','["How many chapters are left?", "What clues has the author given so far?", "What is the weight of the book?", "Who illustrated the cover?"]'::jsonb,1,'Clue-based questions guide inference.','original'),
('110.23.b.5.B',4,'After finishing an article, a reader asks ''What new questions do I have?'' This after-reading step helps the reader...','["avoid analysis", "forget the text", "extend understanding and seek more information", "stop reading"]'::jsonb,2,'Questions can lead to further inquiry.','original'),
('110.23.b.5.C',3,'A chapter title is ''The Storm Gathers.'' What is the best prediction?','["the setting changes to a snowy mountain only", "the story ends happily", "the characters take a nap", "a dangerous event will build in the plot"]'::jsonb,3,'The title signals rising tension.','original'),
('110.23.b.5.C',3,'Text features such as a map, a timeline and sidebars suggest a text that is...','["informational", "a fable", "a poem", "a play"]'::jsonb,0,'Features signal genre.','original'),
('110.23.b.5.C',4,'A reader predicted a character would win a race. The text says he trips on page 40. What should the reader do?','["ignore the page", "revise the prediction with the new evidence", "stop reading", "keep the same prediction"]'::jsonb,1,'Predictions are confirmed or corrected.','original'),
('110.23.b.5.D',3,'Which sentence would help a reader form the sharpest mental image?','["The weather was bad.", "There was a storm.", "Rain hammered the tin roof as lightning split the black sky.", "It was a bad night."]'::jsonb,2,'Specific sensory details create images.','original'),
('110.23.b.5.D',3,'A reader sketches a setting from a description in the text. This helps the reader...','["avoid the theme", "change the plot", "skip passages", "understand and remember details"]'::jsonb,3,'Visualizing deepens comprehension.','original'),
('110.23.b.5.D',4,'Which phrase most strongly supports picturing a crowded market?','["voices overlapped as vendors shouted over piles of fruit", "there were people", "the market existed", "some stalls stood there"]'::jsonb,0,'Sensory and action details create imagery.','original'),
('110.23.b.5.E',3,'A reader compares a character''s fear of speaking in public with her own. This is a connection to...','["society", "personal experience", "the glossary", "another text"]'::jsonb,1,'Text-to-self.','original'),
('110.23.b.5.E',3,'A novel about a plague reminds a student of a documentary about disease. This is a connection to...','["personal experience", "the author''s hobbies", "another text", "a recipe"]'::jsonb,2,'Text-to-text.','original'),
('110.23.b.5.E',4,'A story about unfair labor laws makes a student think about today''s workplace rules. This is a connection to...','["the author''s name", "only the characters", "only the font", "society"]'::jsonb,3,'Text-to-world.','original'),
('110.23.b.5.F',3,'''Marcus kept checking his phone and tapping his foot. When the door opened he jumped to his feet.'' What can be inferred?','["Marcus was anxiously waiting for someone", "Marcus was asleep", "Marcus was baking", "Marcus was bored by a lecture"]'::jsonb,0,'His actions show anticipation.','original'),
('110.23.b.5.F',3,'''The small boat bobbed in the harbor, its paint peeling and its ropes frayed.'' What can be inferred?','["the boat is full of passengers", "the boat is old and not well kept", "the boat is racing", "the boat is brand new"]'::jsonb,1,'Peeling paint and frayed ropes show neglect.','original'),
('110.23.b.5.F',4,'''Nadia hung her medals in the closet and quietly stopped going to practice.'' Which inference is best supported?','["Nadia is practicing more", "Nadia won a national title", "Nadia may have lost interest or confidence in the sport", "Nadia is moving to a new house"]'::jsonb,2,'Hiding medals and quitting practice suggest withdrawal.','original'),
('110.23.b.5.G',3,'Which detail is least important to the key idea of an article about solar power''s benefits?','["solar power lowers electric bills", "solar panels reduce pollution", "sunlight is renewable", "the photographer''s name"]'::jsonb,3,'Details about the photographer don''t support the key idea.','original'),
('110.23.b.5.G',3,'A key idea is the...','["most important point the author makes", "title''s font", "longest sentence", "first word"]'::jsonb,0,'It captures what matters most.','original'),
('110.23.b.5.G',4,'An article gives several examples of animals adapting to deserts. The key idea is probably that...','["animals are all the same", "living things adapt to survive in harsh environments", "deserts are cold", "adapting is impossible"]'::jsonb,1,'Details illustrate adaptation.','original'),
('110.23.b.5.H',3,'Two sources describe different causes of a city''s growth. A student combines the causes into a new explanation. This is...','["copying", "plagiarism", "synthesis", "guessing"]'::jsonb,2,'Combining info creates new understanding.','original'),
('110.23.b.5.H',4,'Source 1 says electric cars cut air pollution. Source 2 says battery production uses scarce minerals. Which synthesis is best?','["cars should never be built", "electric cars have no effect", "the sources agree exactly", "electric cars have environmental benefits but also costs to consider"]'::jsonb,3,'A balanced new idea.','original'),
('110.23.b.5.H',4,'Which sentence is a synthesis of an interview and a chart?','["The interview and chart together show that rising prices have hurt local farmers.", "The chart has three colors.", "The interview was recorded.", "The farmer wore a hat."]'::jsonb,0,'It draws a conclusion from both sources.','original'),
('110.23.b.5.I',3,'A reader realizes she cannot recall what she just read. Which adjustment is best?','["skip to the end", "slow down and re-read the confusing section", "close the book", "read the next page faster"]'::jsonb,1,'Re-reading repairs comprehension.','original'),
('110.23.b.5.I',3,'Using background knowledge while reading means...','["counting paragraphs", "reading only the title", "connecting what you already know to the text", "ignoring new facts"]'::jsonb,2,'Prior knowledge aids understanding.','original'),
('110.23.b.5.I',4,'A reader stops after each page to summarize it in one sentence. This strategy helps the reader...','["skip hard words", "memorize the page numbers", "avoid the main idea", "check understanding as she reads"]'::jsonb,3,'Summarizing monitors comprehension.','original'),
('110.23.b.6.C',3,'Claim: ''The mayor was well liked.'' Which text evidence best supports it?','["Crowds lined the streets to cheer as she passed.", "She wore a blue coat.", "The parade started at noon.", "The street was named Main."]'::jsonb,0,'Cheering crowds show popularity.','original'),
('110.23.b.6.C',4,'A student claims a character is brave but quotes only the character''s name. Why is this weak?','["claims need no evidence", "a name does not show bravery", "quotes must be long", "names are too long"]'::jsonb,1,'Evidence must show the trait.','original'),
('110.23.b.6.C',3,'Which choice is a strong example of citing text evidence?','["The book is long.", "I like the book.", "The text says, ''She stood alone against the crowd,'' showing her courage.", "It was a good story."]'::jsonb,2,'Evidence is a specific quotation tied to the claim.','original'),
('110.23.b.6.D',3,'Which is the best one-sentence summary of a passage about how bees make honey and pollinate crops?','["Bees are insects.", "Honey is sweet.", "Crops grow in fields.", "Bees produce honey and also help plants reproduce by pollinating them."]'::jsonb,3,'It covers both main ideas.','original'),
('110.23.b.6.D',3,'A summary should keep ideas in a logical order. If events happened first, second and third, the summary should...','["present them in the same order", "mix them randomly", "reverse them", "leave out the first"]'::jsonb,0,'Logical order maintains meaning.','original'),
('110.23.b.6.D',4,'Which sentence is a paraphrase of ''The committee postponed the vote until further data was available''?','["The vote was canceled forever.", "The group delayed the vote while waiting for more information.", "The committee voted yesterday.", "The data was lost."]'::jsonb,1,'Paraphrase keeps the same meaning.','original'),
('110.23.b.6.G',3,'''Every light in the house went out, and the whole family fell silent.'' What is the implicit meaning?','["the family is cooking", "the family is celebrating", "the family feels fear or surprise", "the family is asleep"]'::jsonb,2,'Silence in the dark suggests tension.','original'),
('110.23.b.6.G',3,'Which statement gives an explicit meaning?','["The reader feels the cave is scary.", "The reader guesses the cave is haunted.", "The cave seems sad.", "The text says the cave is a mile long."]'::jsonb,3,'Explicit meanings are directly stated.','original'),
('110.23.b.6.G',4,'''By the end of the week, Ali''s lunch table was always empty.'' Which implicit meaning is most likely?','["Ali has become isolated from classmates", "Ali joined the choir", "Ali loves lunch", "Ali made many friends"]'::jsonb,0,'The empty table implies loneliness.','original'),
('110.23.b.7.A',3,'A character cheats to win, loses his friends, and regrets it. Which theme is supported?','["winning is everything", "dishonesty can cost you what you value", "friends are unimportant", "cheating is clever"]'::jsonb,1,'The consequences reveal the theme.','original'),
('110.23.b.7.A',4,'Two poems both describe a storm clearing and new growth. What theme appears across both?','["gardens need fences", "storms are loud", "renewal follows hardship", "rain is bad"]'::jsonb,2,'A shared message.','original'),
('110.23.b.7.A',4,'Which statement is a theme rather than a topic?','["A story about a firefighter", "Courage", "Fire trucks", "Courage means acting even when you are afraid."]'::jsonb,3,'A theme is a complete message.','original'),
('110.23.b.7.B',3,'A stubborn character refuses advice and ends up lost. How does her quality affect the plot?','["it leads to the conflict", "it removes the theme", "it changes the setting", "it ends the conflict"]'::jsonb,0,'Traits drive events.','original'),
('110.23.b.7.B',3,'A generous character shares his only coat, leading a stranger to help him later. This shows that...','["the title is false", "a character''s qualities can shape the resolution", "the conflict is unrelated", "setting is unimportant"]'::jsonb,1,'Kindness results in help.','original'),
('110.23.b.7.B',4,'Which character quality is most likely to cause conflict in a team project?','["asking for ideas", "sharing the work", "refusing to listen to others", "arriving on time"]'::jsonb,2,'Poor listening creates conflict.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'English Language Arts and Reading' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g7_ela_v1'
from (values
('110.23.b.7.C',3,'A story mentions early on that the bridge looks weak. Later it collapses. This technique is...','["a flashback", "personification", "alliteration", "foreshadowing"]'::jsonb,3,'Early hints suggest later events.','original'),
('110.23.b.7.C',3,'The author slows the pace by describing the creaking door, one step at a time. This builds...','["suspense", "a rhyme scheme", "a glossary", "resolution"]'::jsonb,0,'Slow detail increases tension.','original'),
('110.23.b.7.C',4,'Which sentence best foreshadows trouble?','["The grass was green.", "Dark clouds gathered, and the dog refused to leave the porch.", "Lunch was served at noon.", "The sun shone brightly all day."]'::jsonb,1,'Ominous hints foreshadow a problem.','original'),
('110.23.b.7.D',3,'A novel is set in a crowded city during a blackout. How could this setting affect the plot?','["it ensures nothing happens", "it makes the story a poem", "it may create obstacles and danger for characters", "it removes conflict"]'::jsonb,2,'Setting shapes events.','original'),
('110.23.b.7.D',3,'A boy from a farming town struggles in a big city. This shows how setting influences a story''s...','["rhyme", "caption", "stanza", "character"]'::jsonb,3,'Environment shapes behavior.','original'),
('110.23.b.7.D',4,'How does a story set on a spaceship with limited oxygen most likely drive the plot?','["limited resources create urgent choices", "the crew has no problems", "time has no meaning", "the setting is irrelevant"]'::jsonb,0,'Constraints create conflict.','original'),
('110.23.b.8.A',3,'A story about teenagers handling school pressure and friendship in everyday life is...','["a myth", "realistic fiction", "science fiction", "a fable"]'::jsonb,1,'Set in a believable world.','original'),
('110.23.b.8.A',3,'A story with talking animals that ends in a moral is most likely a...','["diary", "biography", "fable", "news report"]'::jsonb,2,'Fables use animals to teach lessons.','original'),
('110.23.b.8.A',4,'A story set in a future with advanced technology and space travel is...','["a biography", "historical fiction", "realistic fiction", "science fiction"]'::jsonb,3,'Imagined science and future settings.','original'),
('110.23.b.8.B',3,'A poem''s stanzas end with the pattern ABAB. This describes its...','["rhyme scheme", "plot", "setting", "meter"]'::jsonb,0,'The ending-sound pattern is the rhyme scheme.','original'),
('110.23.b.8.B',3,'A poet capitalizes a single word to draw attention to it. This is a...','["stage direction", "graphical element for emphasis", "rhyme", "footnote"]'::jsonb,1,'Formatting can emphasize.','original'),
('110.23.b.8.B',4,'A poem uses short, choppy lines and many dashes. What effect could this create?','["a calm lullaby", "a table of data", "a sense of urgency or hesitation", "a long narrative"]'::jsonb,2,'Punctuation and line length affect rhythm.','original'),
('110.23.b.8.C',3,'In a script, how can a playwright show a character is nervous?','["through an index", "through a footnote", "through a glossary", "through stuttering lines and pacing stage directions"]'::jsonb,3,'Dialogue and staging show traits.','original'),
('110.23.b.8.C',3,'An aside in a play is a moment when a character...','["speaks to the audience unheard by others", "reads the stage directions", "leaves the stage forever", "sings the final song"]'::jsonb,0,'Asides reveal private thoughts.','original'),
('110.23.b.8.C',4,'A playwright places two rivals at opposite ends of a long table. What does this staging suggest?','["friendship", "distance and conflict between them", "a rhyme", "a flashback"]'::jsonb,1,'Space reveals relationships.','original'),
('110.23.b.8.F',3,'A news website shows an article, a short video and an interactive graph. This is a...','["limerick", "folktale", "multimodal text", "memoir"]'::jsonb,2,'It uses text, video and graphics.','original'),
('110.23.b.8.F',3,'How can a podcast with a transcript help a reader?','["by removing words", "by blocking pages", "by avoiding facts", "by offering both audio and written information"]'::jsonb,3,'Multiple modes support access.','original'),
('110.23.b.8.F',4,'Which question helps analyze a digital advertisement?','["How do images, color and text work together to persuade?", "How many pixels wide is the logo?", "Who made the cursor?", "What size is the screen?"]'::jsonb,0,'Analysis examines how elements work together.','original'),
('110.23.b.8.D.i',3,'Which detail best supports the thesis ''Teens need more sleep''?','["Some beds are tall.", "Studies show teens focus better after nine hours of rest.", "The sun rises early.", "Pillows are soft."]'::jsonb,1,'Evidence supports the thesis.','original'),
('110.23.b.8.D.i',3,'The thesis of an essay usually appears...','["only in the index", "after the glossary", "in the introduction", "on the copyright page"]'::jsonb,2,'A thesis is stated early.','original'),
('110.23.b.8.D.i',4,'A paragraph includes a claim, a statistic and an example. These details are used to...','["confuse the reader", "avoid evidence", "replace the thesis", "support the controlling idea"]'::jsonb,3,'Evidence supports the main point.','original'),
('110.23.b.8.D.ii',3,'Where would a reader find the sources an author used?','["the references page", "the preface only", "the title", "the cover art"]'::jsonb,0,'References list sources.','original'),
('110.23.b.8.D.ii',3,'An acknowledgements page is used to...','["show maps", "thank people who helped the author", "list definitions", "give page numbers"]'::jsonb,1,'Authors thank helpers.','original'),
('110.23.b.8.D.ii',4,'Why does an author include references?','["to hide the evidence", "to shorten the text", "to credit sources and let readers verify information", "to add rhymes"]'::jsonb,2,'References show credibility.','original'),
('110.23.b.8.D.iii',3,'A textbook chapter has headings and subheadings that group ideas by category. This pattern helps readers...','["avoid evidence", "read backward", "skip details", "see how topics and subtopics relate"]'::jsonb,3,'Hierarchy shows organization.','original'),
('110.23.b.8.D.iii',3,'A text lists causes of the Dust Bowl and then its effects. The pattern is...','["cause and effect", "poetry", "classification only", "dialogue"]'::jsonb,0,'It shows why and what happened.','original'),
('110.23.b.8.D.iii',4,'A passage describes three types of rocks, then breaks each type into examples. This is an example of...','["persuasion", "categories and subcategories", "chronological order", "problem and solution"]'::jsonb,1,'It groups and subdivides.','original'),
('110.23.b.8.E.i',3,'Which sentence states a claim a writer could argue?','["Uniforms are sold in stores.", "Uniforms have buttons.", "Schools should require uniforms.", "Some uniforms are blue."]'::jsonb,2,'A claim is a debatable position.','original'),
('110.23.b.8.E.i',3,'A claim is different from a fact because a claim...','["is always false", "is a quotation", "cannot be questioned", "can be argued"]'::jsonb,3,'Claims are debatable.','original'),
('110.23.b.8.E.i',4,'Which statement is a claim about technology?','["Phones should be allowed in class for research.", "Phones were invented before 2020.", "Phones are made of glass.", "Phones have screens."]'::jsonb,0,'It takes a debatable position.','original'),
('110.23.b.8.E.ii',3,'An author acknowledges the opposing view and explains why it is weaker. This is called...','["telling a joke", "addressing a counterargument", "foreshadowing", "personification"]'::jsonb,1,'Considering alternatives strengthens an argument.','original'),
('110.23.b.8.E.ii',3,'Which type of evidence is an expert''s opinion?','["a statistic", "a rhyme", "testimony", "a map"]'::jsonb,2,'Experts give testimony.','original'),
('110.23.b.8.E.ii',4,'Why does an author include both facts and examples?','["to shorten the argument", "to confuse the reader", "to avoid the topic", "to support the claim in different ways"]'::jsonb,3,'Variety strengthens evidence.','original'),
('110.23.b.8.E.iii',3,'A pamphlet explains ''How to Start Saving Your Allowance'' with simple words and cartoons. The intended audience is probably...','["young students", "retirees", "lawyers", "bank executives"]'::jsonb,0,'Simple wording and cartoons target kids.','original'),
('110.23.b.8.E.iii',4,'A journal article full of technical terms about medicine is aimed at...','["tourists", "medical professionals", "young children", "pet owners"]'::jsonb,1,'Specialized vocabulary signals experts.','original'),
('110.23.b.8.E.iii',3,'An editorial addressed ''Dear voters of our district'' is aimed at...','["visitors", "toddlers", "citizens who can vote", "only athletes"]'::jsonb,2,'The address names the audience.','original'),
('110.23.b.9.A',3,'A text with the headline ''Why You Should Volunteer This Summer'' is mainly written to...','["narrate a story", "describe a mountain", "entertain with jokes", "persuade"]'::jsonb,3,'It tries to convince.','original'),
('110.23.b.9.A',3,'A comic story meant to make readers laugh has the purpose of...','["entertaining", "informing with data", "warning of danger", "persuading voters"]'::jsonb,0,'Humor entertains.','original'),
('110.23.b.9.A',4,'A biography of a scientist ends with how her work changed medicine. What message does the author most likely send?','["scientists work alone", "one person''s work can have lasting impact", "science is unimportant", "medicine never changes"]'::jsonb,1,'The ending highlights the significance.','original'),
('110.23.b.9.B',3,'An author organizes an article as problem, then solutions. How does this support the purpose?','["it makes it a poem", "it hides the problem", "it helps the reader understand and consider actions", "it removes evidence"]'::jsonb,2,'Structure matches the purpose.','original'),
('110.23.b.9.B',4,'A writer uses flashbacks in a mystery. How does this structure help the purpose?','["it ends the story", "it makes the plot linear", "it removes suspense", "it reveals important background at key moments"]'::jsonb,3,'Flashbacks add information.','original'),
('110.23.b.9.B',3,'A text arranged in order of importance helps readers...','["focus on the key points first", "read backward", "ignore the main idea", "avoid details"]'::jsonb,0,'Structure guides attention.','original'),
('110.23.b.9.C',3,'A sidebar in a magazine article is used to...','["end the article", "provide extra related information", "hide the evidence", "replace the title"]'::jsonb,1,'Sidebars add detail.','original'),
('110.23.b.9.C',3,'Why might an author use a graph in an article about rising temperatures?','["to add rhymes", "to tell a joke", "to show trends clearly", "to list rules"]'::jsonb,2,'Graphs show data visually.','original'),
('110.23.b.9.C',4,'An author puts a key quote in large type at the edge of a page. This is called a pull quote, and its purpose is to...','["hide the main idea", "list sources", "end the article", "catch the reader''s attention and highlight a main idea"]'::jsonb,3,'Pull quotes emphasize.','original'),
('110.23.b.9.D',3,'''The city never sleeps'' is an example of...','["personification", "alliteration", "onomatopoeia", "simile"]'::jsonb,0,'A city is given human action.','original'),
('110.23.b.9.D',3,'''Her smile was as bright as the morning sun'' is a...','["metaphor", "simile", "idiom", "hyperbole"]'::jsonb,1,'Uses ''as'' to compare.','original'),
('110.23.b.9.D',4,'''My backpack weighs a ton'' is an example of...','["metaphor", "simile", "hyperbole", "irony"]'::jsonb,2,'Exaggeration for effect.','original'),
('110.23.b.9.E',3,'A text that presents facts without personal feelings uses which kind of point of view?','["first-person emotional", "persuasive", "subjective", "objective"]'::jsonb,3,'Objective accounts avoid opinion.','original'),
('110.23.b.9.E',3,'A narrator who shares personal feelings and opinions about events is using a...','["subjective point of view", "objective point of view", "table of contents", "scientific method"]'::jsonb,0,'Subjective views reveal feelings.','original'),
('110.23.b.9.E',4,'A news report states what happened without opinion words. A blog post says the same event was ''a disaster.'' Which uses a subjective point of view?','["the news report", "the blog post", "neither", "both equally"]'::jsonb,1,'''A disaster'' is an opinion.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'English Language Arts and Reading' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g7_ela_v1'
from (values
('110.23.b.9.F',3,'An author writes a letter that is formal and respectful. The tone is...','["sarcastic", "angry", "serious and polite", "silly"]'::jsonb,2,'Word choice reveals tone.','original'),
('110.23.b.9.F',3,'Which word choice creates a hopeful tone?','["dreary", "gloomy", "bleak", "bright"]'::jsonb,3,'Positive words set a hopeful tone.','original'),
('110.23.b.9.F',4,'An author uses short sentences and sharp words like ''snapped'' and ''slammed.'' What tone is created?','["tense or angry", "playful", "dreamy", "relaxed"]'::jsonb,0,'Sharp diction creates tension.','original'),
('110.23.b.9.G',3,'A speaker says ''You can make a difference today.'' This is an example of...','["onomatopoeia", "direct address", "flashback", "simile"]'::jsonb,1,'The speaker addresses the audience directly.','original'),
('110.23.b.9.G',3,'''Who wouldn''t want cleaner air?'' is a...','["factual question needing an answer", "definition", "rhetorical question", "statistic"]'::jsonb,2,'It makes a point and needs no reply.','original'),
('110.23.b.9.G',4,'''If we allow one exception, soon there will be no rules at all'' is an example of...','["a simile", "a primary source", "a statistic", "a slippery slope fallacy"]'::jsonb,3,'It assumes one step leads to extreme results.','original'),
('110.23.b.10.B.i',3,'Which sentence would best begin the conclusion of an essay?','["In conclusion, regular reading builds vocabulary and focus.", "Reading is on page two.", "The first paragraph is below.", "My dog likes treats."]'::jsonb,0,'Conclusions restate the main idea.','original'),
('110.23.b.10.B.i',4,'A writer jumps from a paragraph about sports to one about cooking with no connection. What is missing?','["a longer title", "a transition and coherence between paragraphs", "a different font", "more adjectives"]'::jsonb,1,'Transitions link ideas.','original'),
('110.23.b.10.B.ii',3,'Which revision adds specific detail to ''The food was good''?','["The food existed.", "The food was fine.", "The tacos were warm, crisp and loaded with fresh salsa.", "I had food."]'::jsonb,2,'Specifics develop an idea.','original'),
('110.23.b.10.B.ii',4,'Which sentence best develops the idea ''Exercise improves health''?','["Exercise has a name.", "Some people exercise.", "Exercise is a thing people do.", "Daily exercise lowers blood pressure and strengthens the heart."]'::jsonb,3,'Facts and details deepen the point.','original'),
('110.23.b.10.C',3,'Which revision removes wordiness from ''Due to the fact that it was raining, we stayed home''?','["Because it was raining, we stayed home.", "It was raining and the reason is that we stayed.", "Due to the fact that raining, home.", "We stayed because of the fact."]'::jsonb,0,'Concise wording keeps meaning.','original'),
('110.23.b.10.C',3,'Which word is the most precise replacement for ''walked'' in ''He walked across the stage nervously''?','["did", "shuffled", "moved", "went"]'::jsonb,1,'Precise verbs clarify action.','original'),
('110.23.b.10.C',4,'A writer notices that three sentences in a row start with ''The.'' Which revision improves style?','["remove the title", "add more ''The''s", "vary the sentence beginnings and structures", "delete all verbs"]'::jsonb,2,'Variety improves flow.','original'),
('110.23.b.10.D.i',3,'Which is a comma splice?','["Because I studied hard, I passed the test.", "I studied hard; I passed the test.", "I studied hard, so I passed the test.", "I studied hard, I passed the test."]'::jsonb,3,'Two independent clauses joined only by a comma.','original'),
('110.23.b.10.D.i',4,'Which is a complete complex sentence?','["When the music stopped, the dancers bowed.", "When the music stopped.", "The dancers bowed, the music stopped.", "Because the dancers."]'::jsonb,0,'It has a dependent and an independent clause.','original'),
('110.23.b.10.D.ii',3,'Which sentence uses verb tenses consistently?','["He will open the door and stepped outside.", "He opens the door and steps outside.", "He opens the door and stepped outside.", "He opened the door and steps outside."]'::jsonb,1,'Both verbs are in the present tense.','original'),
('110.23.b.10.D.ii',3,'Which verb tense shows an action that will happen later?','["past perfect", "present", "future", "past"]'::jsonb,2,'Will + verb is future.','original'),
('110.23.b.10.D.ii',4,'Choose the sentence with a correct past perfect tense.','["By noon, she finish her homework.", "By noon, she has finishing her homework.", "By noon, she will had finished.", "By noon, she had finished her homework."]'::jsonb,3,'Had + past participle.','original'),
('110.23.b.10.D.iii',3,'Which word best joins ''He studied for hours'' and ''he failed the test'' to show contrast?','["nevertheless", "moreover", "therefore", "similarly"]'::jsonb,0,'Nevertheless shows contrast.','original'),
('110.23.b.10.D.iii',4,'Which sentence punctuates a conjunctive adverb correctly?','["The bus was late, however we made it on time.", "The bus was late; however, we made it on time.", "The bus was late; however we made it, on time.", "The bus was late however; we made it on time."]'::jsonb,1,'Semicolon before and comma after.','original'),
('110.23.b.10.D.iii',3,'Which conjunctive adverb adds information?','["instead", "however", "furthermore", "otherwise"]'::jsonb,2,'Furthermore adds to an idea.','original'),
('110.23.b.10.D.iv',3,'Choose the correct verb: ''The list of ingredients ____ long.''','["are", "were", "be", "is"]'::jsonb,3,'The subject ''list'' is singular.','original'),
('110.23.b.10.D.iv',4,'Choose the correct verb: ''The students in the back row ____ talking.''','["are", "was", "is", "be"]'::jsonb,0,'The subject ''students'' is plural.','original'),
('110.23.b.10.D.iv',3,'Which word group is a prepositional phrase?','["the boy ran", "in the green boat", "and then left", "rowed quickly"]'::jsonb,1,'Preposition plus object.','original'),
('110.23.b.10.D.v',3,'Choose the correct pronoun: ''Each student must bring ____ own book.''','["our", "their-selves", "his or her", "they"]'::jsonb,2,'Singular antecedent needs a singular pronoun.','original'),
('110.23.b.10.D.v',3,'What is the antecedent of a pronoun?','["the punctuation mark before it", "the verb that follows it", "the last word of the sentence", "the noun the pronoun refers back to"]'::jsonb,3,'An antecedent is the word a pronoun replaces.','original'),
('110.23.b.10.D.v',4,'Which sentence has correct pronoun-antecedent agreement?','["The team celebrated its victory.", "The team celebrated their victory loudly together alone.", "The team celebrated his and her victories.", "The team celebrated they victory."]'::jsonb,0,'Collective noun treated as one unit.','original'),
('110.23.b.10.D.vi',3,'Which pair completes the sentence: ''____ the movie ____ the book was good''?','["Either / and", "Neither / nor", "Both / or", "Not only / but or"]'::jsonb,1,'Correlative pair neither/nor.','original'),
('110.23.b.10.D.vi',4,'Which sentence correctly uses a subordinating conjunction?','["Since, it was late we left early.", "Since it was late, and we left early.", "Since it was late, we left early.", "Since it was late we, left early."]'::jsonb,2,'A comma follows the introductory clause.','original'),
('110.23.b.10.D.vii',3,'Which word group needs capital letters?','["the nearby hills", "a large lake", "an old river", "the Pacific Ocean"]'::jsonb,3,'Specific geographic names are capitalized.','original'),
('110.23.b.10.D.vii',3,'Which of these should be capitalized in a sentence?','["Senator Alvarez", "the senators", "a senator", "any senator"]'::jsonb,0,'Titles before names are capitalized.','original'),
('110.23.b.10.D.vii',2,'Which word is always capitalized?','["me", "I", "we", "you"]'::jsonb,1,'The pronoun I is always capitalized.','original'),
('110.23.b.10.D.viii',3,'Which sentence uses a semicolon correctly?','["I like; hiking my brother prefers swimming.", "I like hiking my brother; prefers swimming.", "I like hiking; my brother prefers swimming.", "I like hiking my; brother prefers swimming."]'::jsonb,2,'A semicolon joins related independent clauses.','original'),
('110.23.b.10.D.viii',3,'Which sentence correctly sets off a nonessential phrase with commas?','["My cousin who lives in Dallas, visited us.", "My, cousin who lives in Dallas visited us.", "My cousin, who lives in Dallas visited us.", "My cousin, who lives in Dallas, visited us."]'::jsonb,3,'Commas surround nonessential information.','original'),
('110.23.b.10.D.viii',4,'Which list is punctuated correctly?','["We packed tents, flashlights, and sleeping bags.", "We packed tents, flashlights and, sleeping bags.", "We packed tents flashlights and, sleeping bags.", "We packed, tents flashlights, and sleeping bags."]'::jsonb,0,'Commas separate items in a series.','original'),
('110.23.b.10.D.ix',2,'Which sentence uses the correct form?','["It time to go home.", "It''s time to go home.", "Its time to go home.", "Its'' time to go home."]'::jsonb,1,'It''s means it is.','original'),
('110.23.b.10.D.ix',3,'Choose the correct word: ''The ____ of the new rule was positive.''','["effects-on", "affect", "effect", "affects"]'::jsonb,2,'Effect is a noun meaning result.','original'),
('110.23.b.12.E',3,'A letter written by a soldier in 1944 is a...','["encyclopedia", "textbook", "secondary source", "primary source"]'::jsonb,3,'Firsthand documents are primary.','original'),
('110.23.b.12.E',4,'A student needs a secondary source about the Great Depression. Which fits?','["a history book written in 2015", "a newspaper from 1930", "a diary from 1931", "a photograph from 1932"]'::jsonb,0,'Secondary sources analyze primary ones.','original'),
('110.23.b.12.E',3,'An interview recorded with a witness of an event is a...','["dictionary", "primary source", "secondary source", "textbook"]'::jsonb,1,'A firsthand account.','original'),
('110.23.b.12.G',3,'Rewriting a source''s idea in your own words and crediting it is...','["stealing", "forgery", "ethical paraphrasing", "plagiarism"]'::jsonb,2,'Credit keeps it ethical.','original'),
('110.23.b.12.G',3,'Which is plagiarism?','["summarizing with a citation", "quoting with credit", "paraphrasing and citing", "turning in a classmate''s essay as your own"]'::jsonb,3,'Passing off others'' work is plagiarism.','original'),
('110.23.b.12.G',4,'A student copies a paragraph and changes only three words without citing. This is still...','["plagiarism", "synthesis", "paraphrasing", "summarizing"]'::jsonb,0,'Minor word changes are not enough.','original'),
('110.23.b.12.H.i',3,'Which website is most reliable for scientific data on weather?','["a celebrity gossip blog", "a national weather service", "an anonymous forum", "an online ad"]'::jsonb,1,'Government science agencies are credible.','original'),
('110.23.b.12.H.i',4,'A reader finds an article with no author, no date and no sources. What should the reader conclude?','["dates don''t matter", "the article is probably perfect", "the article may not be credible", "sources are optional"]'::jsonb,2,'Missing details reduce credibility.','original'),
('110.23.b.12.H.i',3,'Bias in a source means the source...','["is balanced", "is always true", "is written by an expert", "favors one side unfairly"]'::jsonb,3,'Biased sources lack balance.','original'),
('110.23.b.12.H.ii',3,'''Everyone knows this phone is the best'' is an example of...','["an unsupported claim or bandwagon appeal", "a primary source", "a statistic", "a definition"]'::jsonb,0,'It relies on popularity, not evidence.','original'),
('110.23.b.12.H.ii',4,'A commercial shows a happy family to sell cereal but gives no nutrition facts. This is a(n)...','["scientific study", "emotional appeal", "statistic", "primary source"]'::jsonb,1,'It appeals to feelings.','original'),
('110.23.b.12.H.ii',4,'''Those people never follow the rules'' about an entire group is an example of...','["a metaphor", "a quotation", "a stereotype", "a fact"]'::jsonb,2,'A broad unfair generalization.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'English Language Arts and Reading' and d.language = 'en'
